mapper.insert:
INSERT INTO order_claim_stock_result(id,claim_id,rental_order_id,rental_order_item_id,original_reservation_id,sn_id,quantity,outcome,
    source_type,decision_id,replaces_id,result_status,recorded_by,remark,created_at) SELECT #{fact.id},c.id,c.rental_order_id,#{fact.itemId},#{fact.reservationId},
    #{fact.snId},#{fact.quantity},#{fact.outcome},#{fact.sourceType},#{fact.decisionId},#{replaces},'recorded',#{fact.actor},#{fact.remark},#{fact.createdAt} FROM order_claim c WHERE c.id=#{fact.claimId}

mapper.update:
UPDATE prop_sku_stock SET total_quantity=total_quantity-#{quantity},rentable_base_quantity=rentable_base_quantity-#{quantity},
    available_quantity=LEAST(available_quantity,rentable_base_quantity),
    lost_quantity=lost_quantity+IF(#{lost},#{quantity},0),scrapped_quantity=scrapped_quantity+IF(#{scrap},#{quantity},0),updated_at=#{at}
    WHERE sku_id=#{sku} AND total_quantity>=#{quantity} AND rentable_base_quantity>=#{quantity}

mapper.select:
SELECT DISTINCT c.id FROM order_claim c WHERE c.claim_status='executing' AND c.id>#{after}
    AND (EXISTS(SELECT 1 FROM order_claim_stock_result f WHERE f.claim_id=c.id AND f.result_status='recorded')
      OR NOT EXISTS(SELECT 1 FROM inventory_reservation r WHERE r.rental_order_id=c.rental_order_id AND r.reservation_status='disputed_holding')) ORDER BY c.id LIMIT 100

mapper.update:
UPDATE order_claim_stock_result f SET result_status='replaced' WHERE claim_id=#{claim} AND original_reservation_id=#{reservation}
    AND result_status IN ('recorded','repair_pending') AND (SELECT n FROM (SELECT COALESCE(SUM(quantity),0) n FROM order_claim_stock_result WHERE claim_id=#{claim}
    AND original_reservation_id=#{reservation} AND result_status IN ('recorded','repair_pending')) AS prior)>#{remaining}

mapper.select:
SELECT EXISTS(SELECT 1 FROM rental_order o WHERE id=#{id}
    AND deposit_paid_amount_fen=deposit_refunded_amount_fen+deposit_deducted_amount_fen AND NOT EXISTS(
    SELECT 1 FROM refund_order r WHERE r.rental_order_id=o.id AND r.refund_status NOT IN ('success','cancelled')))
